python3 -c "
import os

EXTS = ('.md', '.sh', '.yaml', '.yml', '.json', '.ts', '.tsx', '.py', '.txt', '.mako')

converted = 0
for root, dirs, files in os.walk('.'):
    if any(p in root for p in ['node_modules', '.git', '.expo']):
        continue
    for f in files:
        if f.endswith(EXTS):
            path = os.path.join(root, f)
            try:
                with open(path, 'rb') as fp:
                    content = fp.read()
                if b'\r\n' in content:
                    with open(path, 'wb') as fp:
                        fp.write(content.replace(b'\r\n', b'\n'))
                    converted += 1
            except Exception as e:
                print(f'Error {path}: {e}')

print(f'Converted {converted} files to LF')
"
